<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { useAuthStore } from '@stores/useAuthStore'
import { useVoiceStore } from '@stores/useVoiceStore'
import { normalizeVoiceCode, parsePeerJsTarget } from '@/voice/PeerJsTarget'

const router = useRouter()
const route = useRoute()
const authStore = useAuthStore()
const voiceStore = useVoiceStore()

// Code input state
const code = ref('')
const error = ref<string | null>(null)
const isLoading = ref(false)
const isConnecting = ref(false)
const showCodeFromUrl = ref(false)
const urlCode = ref<string | null>(null)

// Computed
const codeLength = computed(() => code.value.length)
const isCodeValid = computed(() => parsePeerJsTarget(code.value) !== null)
const canSubmit = computed(() => isCodeValid.value && !isLoading.value && !isConnecting.value)
const showOpenLinkButton = computed(() => showCodeFromUrl.value && urlCode.value)

// Extract code from URL (query param ?code= or hash #/join/12345)
function extractCodeFromUrl(): string | null {
  // Check query parameter ?code=12345
  const routeQueryCode = route.query['code']
  const queryCode = typeof routeQueryCode === 'string'
    ? routeQueryCode
    : new URLSearchParams(window.location.search).get('code') ?? undefined
  if (queryCode && parsePeerJsTarget(queryCode)) {
    return normalizeVoiceCode(queryCode)
  }

  // Check hash route /join/12345
  const hashCode = route.params['code'] as string | undefined
  if (hashCode && parsePeerJsTarget(hashCode)) {
    return normalizeVoiceCode(hashCode)
  }

  // Check full hash #/join/12345 (for client-side routing)
  if (window.location.hash) {
    const hashMatch = window.location.hash.match(/#\/join\/([^/?]+)/i)
    if (hashMatch) {
      return normalizeVoiceCode(hashMatch[1] ?? '')
    }
  }

  return null
}

// Copy code to clipboard
async function copyCode() {
  if (!code.value) return
  try {
    await navigator.clipboard.writeText(code.value)
    // Visual feedback
    const copyBtn = document.querySelector('.btn-copy')
    copyBtn?.classList.add('copied')
    setTimeout(() => copyBtn?.classList.remove('copied'), 1500)
  } catch {
    // Fallback for older browsers
    const textarea = document.createElement('textarea')
    textarea.value = code.value
    textarea.style.position = 'fixed'
    textarea.style.opacity = '0'
    document.body.appendChild(textarea)
    textarea.select()
    document.execCommand('copy')
    document.body.removeChild(textarea)
  }
}

// Keep the server peer ID and normalize only the local code part.
function handleCodeInput(event: Event) {
  const input = event.target as HTMLInputElement
  const value = normalizeVoiceCode(input.value).slice(0, 10)
  code.value = value
  input.value = value
  error.value = null
}

// Handle paste event
function handlePaste(event: ClipboardEvent) {
  const pasted = event.clipboardData?.getData('text') ?? ''
  const pastedCode = normalizeVoiceCode(pasted).slice(0, 10)
  if (pastedCode) {
    event.preventDefault()
    code.value = pastedCode
    error.value = null
  }
}

// Submit code and connect
async function handleSubmit() {
  if (!isCodeValid.value || isLoading.value) return

  error.value = null
  isLoading.value = true

  try {
    isConnecting.value = true
    const peerTarget = parsePeerJsTarget(code.value)
    const peerHost = import.meta.env['VITE_PEERJS_HOST'] || '0.peerjs.com'
    if (peerTarget) {
      authStore.preparePeerJsAuth(code.value)
      await voiceStore.connect({
        mode: 'peerjs',
        pluginPeerId: peerTarget.peerId,
        host: peerHost,
        port: Number(import.meta.env['VITE_PEERJS_PORT'] || 443),
        path: import.meta.env['VITE_PEERJS_PATH'] || '/',
        secure: import.meta.env['VITE_PEERJS_SECURE'] !== 'false',
        key: import.meta.env['VITE_PEERJS_KEY'] || 'peerjs',
        token: import.meta.env['VITE_PEERJS_TOKEN'] || '',
        code: peerTarget.value,
      })
    } else {
      await authStore.joinWithCode(code.value)
      const wsUrl = import.meta.env['VITE_WS_URL'] || 'ws://localhost:8080/ws'
      await voiceStore.connect({
        mode: 'server',
        url: wsUrl,
        token: authStore.token ?? '',
        roomId: code.value,
        displayName: authStore.username,
      })
    }
    await router.push('/voice')

  } catch (err) {
    const message = err instanceof Error ? err.message : 'Verbindung fehlgeschlagen'
    if (authStore.token?.startsWith('peerjs:')) authStore.clearAuth()
    error.value = message
    isConnecting.value = false
  } finally {
    isLoading.value = false
  }
}

// Handle Enter key
function handleKeydown(event: KeyboardEvent) {
  if (event.key === 'Enter' && canSubmit.value) {
    handleSubmit()
  }
}

// Open the join link (for sharing)
function openJoinLink() {
  if (!urlCode.value) return
  const joinUrl = new URL(router.resolve({ name: 'Join', params: { code: urlCode.value } }).href, window.location.origin).href
  window.open(joinUrl, '_blank')
}

// Initialize on mount
onMounted(() => {
  authStore.restoreAuth()

  // Extract code from URL
  const extractedCode = extractCodeFromUrl()
  if (extractedCode) {
    urlCode.value = extractedCode
    code.value = extractedCode
    showCodeFromUrl.value = true
  }

  // If already authenticated and no code in URL, redirect to voice
  if (authStore.isAuthenticated && !extractedCode && route.name === 'Login') {
    router.push('/voice')
  }
})

// Watch for route changes (e.g., user navigates to /join/12345 from within app)
watch(() => route.fullPath, () => {
  const extractedCode = extractCodeFromUrl()
  if (extractedCode) {
    urlCode.value = extractedCode
    code.value = extractedCode
    showCodeFromUrl.value = true
  } else {
    urlCode.value = null
    showCodeFromUrl.value = false
    // Don't clear code.value if user typed it manually
  }
})
</script>

<template>
  <div class="login-container">
    <div class="login-card">
      <div class="login-header">
        <h1>SimpleVoiceChat</h1>
        <p class="subtitle">Echtzeit-Sprachkommunikation</p>
      </div>

      <div class="instruction-card">
        <div class="instruction-icon" aria-hidden="true">
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
          </svg>
        </div>
        <div class="instruction-text">
          <p>Gib in Minecraft <code>/voice link</code> ein, um einen Einmal-Code zu erhalten.</p>
          <p class="instruction-hint">Der Code ist gleichzeitig Peer-ID und Berechtigung für genau eine Verbindung.</p>
        </div>
      </div>

      <div v-if="error" class="error-message" role="alert">
        {{ error }}
      </div>

      <form @submit.prevent="handleSubmit" class="login-form">
        <div class="form-group">
          <label for="code" class="form-label">
            PeerJS-Code
            <span class="code-counter">{{ codeLength }}</span>
          </label>
          <div class="code-input-wrapper">
            <input
              id="code"
              v-model="code"
              type="text"
            inputmode="text"
            pattern="[A-Za-z0-9]{10}"
              maxlength="10"
              autocomplete="off"
              :disabled="isLoading || isConnecting"
              @input="handleCodeInput"
              @paste="handlePaste"
              @keydown="handleKeydown"
              placeholder="K7P4QX9LM2"
              aria-describedby="code-hint"
            />
            <button
              type="button"
              class="btn-copy"
              @click="copyCode"
              :disabled="!code || isLoading"
              aria-label="Code in Zwischenablage kopieren"
              title="Code kopieren"
            >
              <svg class="copy-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
              </svg>
              <svg class="copied-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                <polyline points="20 6 9 17 4 12" />
              </svg>
            </button>
          </div>
          <p id="code-hint" class="form-hint">10-stelliger Code aus Minecraft</p>
        </div>

        <button
          type="submit"
          class="btn btn-primary btn-block"
          :disabled="!canSubmit"
          :class="{ 'btn-loading': isConnecting }"
        >
          <span v-if="isConnecting" class="btn-spinner" aria-hidden="true"></span>
          <span v-if="isLoading && !isConnecting">Prüfe Code...</span>
          <span v-else-if="isConnecting">Verbinde...</span>
          <span v-else>Beitreten</span>
        </button>
      </form>

      <div v-if="showOpenLinkButton" class="open-link-section">
        <button type="button" class="btn btn-outline" @click="openJoinLink">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
            <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
            <polyline points="15 3 21 3 21 9" />
            <line x1="10" y1="14" x2="21" y2="3" />
          </svg>
          Link öffnen (Code: {{ urlCode }})
        </button>
        <p class="link-hint">Teile diesen Link, damit andere dem Voicechat beitreten können.</p>
      </div>

      <div class="divider">
        <span>oder</span>
      </div>

      <p class="footer-hint">
        Kein Minecraft Server? <a href="https://github.com/MundoFahrer/SimpleVoiceChatWeb" target="_blank" rel="noopener noreferrer">Mehr erfahren</a>
      </p>
    </div>
  </div>
</template>

